const item = $input.first().json;
const metrics = item.metrics || [];
const notableChanges = item.notableChanges || [];

const fmtNum = (n) => {
  if (n === null || n === undefined || isNaN(n)) return 'N/A';
  return Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
};

const fmtPct = (n) => {
  if (n === null || n === undefined || isNaN(n)) return 'N/A';
  const sign = n > 0 ? '+' : '';
  return sign + Number(n).toFixed(1) + '%';
};

const metricsTableRowsHtml = metrics.map((m) => {
  const up = (m.pctChange || 0) >= 0;
  const trendClass = up ? 'trend-up' : 'trend-down';
  const barClass = up ? 'bar-up' : 'bar-down';
  const flagBadge = m.flagged ? ' <span class="flag-badge">FLAGGED</span>' : '';
  const magnitude = Math.max(6, Math.min(Math.abs(m.pctChange || 0), 40) / 40 * 100);
  return '<tr><td class="metric-name">' + m.name + '</td><td class="metric-value">' + fmtNum(m.previousValue) + '</td><td class="metric-value">' + fmtNum(m.currentValue) + '</td><td class="metric-delta ' + trendClass + '">' + fmtPct(m.pctChange) + flagBadge + '</td><td class="metric-bar-cell"><div class="bar-track"><div class="bar-fill ' + barClass + '" style="width:' + magnitude.toFixed(0) + '%"></div></div></td></tr>';
}).join('\n');

const notableChangesListHtml = notableChanges.length
  ? notableChanges.map((c) => '<li><strong>' + c.metric + '</strong> moved ' + c.direction + ' ' + fmtPct(c.change_pct) + ' &mdash; ' + c.comment + '</li>').join('\n')
  : '<li>No notable changes above threshold this period.</li>';

const sentimentColors = { positive: '#1a7f4e', neutral: '#5b6472', mixed: '#a3690a', negative: '#b23b3b' };
const sentimentColor = sentimentColors[item.overallSentiment] || sentimentColors.neutral;

const now = new Date();
const generatedDateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
const agencyInitial = (item.agencyName || 'A').trim().charAt(0).toUpperCase();

return [{
  json: Object.assign({}, item, {
    metricsTableRowsHtml: metricsTableRowsHtml,
    notableChangesListHtml: notableChangesListHtml,
    sentimentColor: sentimentColor,
    generatedDateStr: generatedDateStr,
    agencyInitial: agencyInitial,
  }),
}];

