const html = $input.first().json.html;
const base64 = Buffer.from(html, 'utf-8').toString('base64');
return [{
  json: {},
  binary: {
    data: {
      data: base64,
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html',
    },
  },
}];

const raw = $input.first().json;
const rawMsg = raw.error || raw.message || (raw.error && raw.error.message) || JSON.stringify(raw);
const friendly = 'PDF rendering via the hosted API (PDFShift) failed: ' + rawMsg + '. If the PDFShift credential has not been configured yet, add a Header Auth credential (Header Name: X-API-Key, Header Value: your PDFShift key) to the "Convert HTML to PDF (PDFShift API)" node, or set Config.pdfEngine back to "gotenberg".';
return [{ json: { friendlyError: friendly } }];
